function localDirtyAddresses(){const b=state.base.sheets[0].cells,c=sheet().cells,s=new Set;for(const a of new Set([...Object.keys(b),...Object.keys(c)]))if((b[a]||'')!==(c[a]||''))s.add(a);return s}
function onRemote(e){if(e.userId===state.userId){}const dirtySet=localDirtyAddresses(),over=e.changes.filter(x=>dirtySet.has(x.address));const local=new Map([...dirtySet].map(a=>[a,raw(a)]));state.base=structuredClone(e.workbook);state.revision=e.revision;state.workbook=structuredClone(e.workbook);for(const [a,v] of local){if(v==='')delete sheet().cells[a];else sheet().cells[a]=v}if(over.length){for(const x of over)state.conflicts.add(x.address);setStatus('Remote conflict','failed');toast(`Remote change conflicts at ${over.map(x=>x.address).join(', ')}`,true)}else if(dirtySet.size){setStatus('Unsaved changes · remote changes merged','dirty');toast('Remote saved changes merged with your draft')}else{state.dirty=false;setStatus('Saved · updated remotely','saved');toast('Workbook updated by a collaborator')}render();loadRevisions()}

function renderRemote(){$$('.remote-outline').forEach(x=>x.remove());const others=state.presence.filter(p=>p.sessionId!==state.sessionId);others.forEach((p,i)=>{const q=parseRange(p.address);if(!q)return;const first=cellEl(q.r1,q.c1),last=cellEl(q.r2,q.c2);if(!first||!last)return;const d=document.createElement('div');d.className='remote-outline'+(others.filter(x=>x.address===p.address).length>1?' multi':'');const color=colors[i%colors.length];Object.assign(d.style,{left:first.offsetLeft+'px',top:first.offsetTop+'px',width:(last.offsetLeft+last.offsetWidth-first.offsetLeft)+'px',height:(last.offsetTop+last.offsetHeight-first.offsetTop)+'px',borderColor:color,color});$('#grid-scroll').appendChild(d)})}
function sendPresence(){if(!state.workbook)return;fetch('/api/presence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId:state.sessionId,userId:state.userId,address:rangeAddress(range())})})}
function showPresence(list){state.presence=list;const counts={};for(const p of list)counts[p.userId]=(counts[p.userId]||0)+1;$('#presence-count').textContent=` · ${list.length} view${list.length===1?'':'s'}`;$('#presence').innerHTML=list.map((p,i)=>`<span class="person"><span class="dot" style="background:${colors[i%colors.length]}"></span>${escapeHtml(p.name)}${counts[p.userId]>1?` (${counts[p.userId]} views)`:''} · ${p.address}</span>`).join('');renderRemote()}

function findNext(){const term=$('#find').value.toLowerCase();if(!term)return toast('Enter text to find',true);const all=[];for(let r=1;r<=ROWS;r++)for(let c=1;c<=COLS;c++){const a=addr(r,c);if(raw(a).toLowerCase().includes(term)||display(a).toLowerCase().includes(term))all.push({r,c})}if(!all.length){$('#find-result').textContent='No matches';return}const idx=all.findIndex(x=>x.r>state.focus.r||(x.r===state.focus.r&&x.c>state.focus.c));const x=all[idx<0?0:idx];select(x.r,x.c);$('#find-result').textContent=`Match ${all.indexOf(x)+1} of ${all.length}`}
function replaceOne(){const term=$('#find').value;if(!term)return;const a=addr(state.focus.r,state.focus.c),v=raw(a);if(v.toLowerCase().includes(term.toLowerCase()))commit([{a,v:v.replace(new RegExp(term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i'),$('#replace').value)}],'Replace');else findNext()}
function replaceAll(){const term=$('#find').value;if(!term)return toast('Enter text to find',true);const re=new RegExp(term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),ch=[];for(const [a,v] of Object.entries(sheet().cells))if(v.toLowerCase().includes(term.toLowerCase()))ch.push({a,v:v.replace(re,$('#replace').value)});commit(ch,'Replace All');toast(`Replaced ${ch.length} cell${ch.length===1?'':'s'}`)}
async function showHistory(){const a=addr(state.focus.r,state.focus.c),items=await api(`/api/workbooks/${state.workbook.id}/history/${sheet().id}/${a}`);showDialog(`History for ${a}`,items.length?items.map(x=>`<div class="history-item"><b>${escapeHtml(x.userName)}</b> · revision ${x.revision}<br><small>${new Date(x.changedAt).toLocaleString()}</small><br><code>${escapeHtml(x.oldValue||'(blank)')} → ${escapeHtml(x.newValue||'(blank)')}</code></div>`).join(''):'<p>No saved changes for this cell.</p>')}
async function loadRevisions(){state.revisions=await api(`/api/workbooks/${state.workbook.id}/revisions`)}
async function showRevisions(){await loadRevisions();showDialog('Revision history',state.revisions.map(x=>`<div class="revision-item"><span><b>Revision ${x.number}</b><br><small>${new Date(x.createdAt).toLocaleString()} · ${x.userId||'system'}</small></span><span><button data-preview="${x.number}">Preview</button> <button data-restore="${x.number}">Restore as draft</button></span></div>`).join(''))}
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal()}
async function previewRevision(n,restore=false){const j=await api(`/api/workbooks/${state.workbook.id}/revisions/${n}`);if(!restore){showDialog(`Preview revision ${n}`,`<p>${escapeHtml(j.workbook.title)} · ${Object.keys(j.workbook.sheets[0].cells).length} populated cells</p><pre>${escapeHtml(JSON.stringify(j.workbook.sheets[0].cells,null,2))}</pre>`);return}const before=structuredClone(sheet().cells),after=j.workbook.sheets[0].cells,ch=[];for(const a of new Set([...Object.keys(before),...Object.keys(after)]))if((before[a]||'')!==(after[a]||''))ch.push({a,v:after[a]||''});commit(ch,`Restore revision ${n}`);$('#dialog').close();toast(`Revision ${n} loaded as unsaved draft`)}

function events(){const es=new EventSource(`/api/events?sessionId=${encodeURIComponent(state.sessionId)}`);es.addEventListener('presence',e=>showPresence(JSON.parse(e.data)));es.addEventListener('saved',e=>onRemote(JSON.parse(e.data)))}
async function init(){buildGrid();const [users,data]=await Promise.all([api('/api/users'),api('/api/workbooks/ops-plan')]);$('#user').innerHTML=users.map(u=>`<option value="${u.id}">${escapeHtml(u.name)}</option>`).join('');state.userId=users[0].id;state.workbook=data.workbook;state.base=structuredClone(data.workbook);state.revision=data.revision;$('#title').textContent=state.workbook.title;$('#sheet-tab').textContent=sheet().name;setStatus('Saved','saved');render();loadRevisions();events();sendPresence();$('#grid').focus()}

$('#grid').addEventListener('mousedown',e=>{const el=e.target.closest('.cell');if(!el)return;const r=+el.dataset.r,c=+el.dataset.c;if(state.editing&&$('#cell-editor').value.startsWith('=')){insertReference(e.shiftKey?rangeAddress({r1:Math.min(state.anchor.r,r),c1:Math.min(state.anchor.c,c),r2:Math.max(state.anchor.r,r),c2:Math.max(state.anchor.c,c)}):addr(r,c));e.preventDefault();return}select(r,c,e.shiftKey);const move=ev=>{const x=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.cell');if(x)select(+x.dataset.r,+x.dataset.c,true,false)};const up=()=>{removeEventListener('mousemove',move);removeEventListener('mouseup',up)};addEventListener('mousemove',move);addEventListener('mouseup',up)});
$('#grid').addEventListener('dblclick',e=>{if(e.target.closest('.cell'))beginEdit()});
$('#grid').addEventListener('keydown',e=>{if(state.editing)return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();return e.shiftKey?redo():undo()}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();return redo()}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab','Enter'].includes(e.key)){e.preventDefault();let {r,c}=state.focus;if(e.key==='ArrowUp'||(e.key==='Enter'&&e.shiftKey))r--;else if(e.key==='ArrowDown'||e.key==='Enter')r++;else if(e.key==='ArrowLeft'||(e.key==='Tab'&&e.shiftKey))c--;else c++;return select(r,c,e.shiftKey&&e.key.startsWith('Arrow'))}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();return commit(currentValues().map(x=>({a:x.a,v:''})),'Clear')}if(e.key==='F2'||e.key==='='){e.preventDefault();return beginEdit(e.key==='='?'=':null)}if(!mod&&e.key.length===1){e.preventDefault();beginEdit(e.key)}});
$('#cell-editor').addEventListener('input',e=>editInput(e.target.value,e.target));$('#cell-editor').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finishEdit(false)}else if(e.key==='Enter'||e.key==='Tab'){e.preventDefault();finishEdit(true,e.key==='Enter'?(e.shiftKey?-1:1):0)}});
$('#formula').addEventListener('focus',()=>{if(!state.editing)beginEdit()});$('#formula').addEventListener('input',e=>editInput(e.target.value,e.target));$('#formula').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();finishEdit(true)}if(e.key==='Escape')finishEdit(false)});
document.addEventListener('click',e=>{const f=e.target.dataset.fn;if(f){const ed=$('#cell-editor'),token=(ed.value.match(/([A-Za-z]*)$/)||[])[1];ed.value=ed.value.slice(0,-token.length)+f+'(';editInput(ed.value,ed);ed.focus()}const p=e.target.dataset.preview,r=e.target.dataset.restore;if(p)previewRevision(p);if(r)previewRevision(r,true)});
document.addEventListener('copy',e=>{if(!state.workbook||/INPUT/.test(e.target.tagName))return;e.preventDefault();e.clipboardData.setData('text/plain',selectedMatrix().map(r=>r.join('\t')).join('\n'));toast('Copied selection')});document.addEventListener('cut',e=>{if(/INPUT/.test(e.target.tagName))return;e.preventDefault();e.clipboardData.setData('text/plain',selectedMatrix().map(r=>r.join('\t')).join('\n'));commit(currentValues().map(x=>({a:x.a,v:''})),'Cut')});document.addEventListener('paste',e=>{if(/INPUT/.test(e.target.tagName))return;e.preventDefault();pasteText(e.clipboardData.getData('text/plain'))});
$('#goto-form').addEventListener('submit',e=>{e.preventDefault();const q=parseRange($('#namebox').value);if(!q)return toast('Invalid address or range',true);state.anchor={r:q.r1,c:q.c1};state.focus={r:q.r2,c:q.c2};render();cellEl(q.r1,q.c1).scrollIntoView({block:'nearest',inline:'nearest'});sendPresence()});
$('#save').onclick=save;$('#undo').onclick=undo;$('#redo').onclick=redo;$('#fill-down').onclick=()=>fill('down');$('#fill-right').onclick=()=>fill('right');$('#find-next').onclick=findNext;$('#replace-one').onclick=replaceOne;$('#replace-all').onclick=replaceAll;$('#history').onclick=showHistory;$('#revisions').onclick=showRevisions;$('#dialog-close').onclick=()=>$('#dialog').close();$('#user').onchange=e=>{state.userId=e.target.value;sendPresence()};
addEventListener('beforeunload',()=>navigator.sendBeacon('/api/presence/close',new Blob([JSON.stringify({sessionId:state.sessionId})],{type:'application/json'})));
init().catch(e=>{setStatus('Failed to load','failed');toast(e.message,true)});
EOF
cat > /app/APP_MANIFEST.md <<'EOF'
# GridForge

```bash start
cd /app && npm start
```

- **SQLite database:** `/app/gridforge.sqlite`
- **Web address:** `http://localhost:${PORT:-3000}` (listens on `0.0.0.0`)
- **Main API routes:**
  - `GET /api/users`
  - `GET /api/workbooks`
  - `GET /api/workbooks/:id`
  - `POST /api/workbooks/:id/save`
  - `GET /api/workbooks/:id/revisions`
  - `GET /api/workbooks/:id/revisions/:revision`
  - `GET /api/workbooks/:id/history/:sheet/:address`
  - `GET /api/events` (server-sent collaboration events)
  - `POST /api/presence`
EOF
